parameters.query:
SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.id DESC), '[]'::jsonb) AS borradores
FROM public.reservas_draft d
WHERE d.subscriber_id::text = $1::text;

parameters.jsCode:
// Solo se cambia una pre-reserva ACTIVA y SIN PAGAR. Si ya pagó o está en revisión de pago,
// el cambio lo hace una asesora (política vigente).
const entrada = $('Cambio de servicio solicitado').first().json || {};
const pago = $input.first().json || {};
const filas = Array.isArray(pago.borradores) ? pago.borradores : [];

const texto = v => String(v ?? '').trim();
const activas = new Set(['esperando_pago','pendiente_pago','creando_retencion']);
const sinPagar = d => d.pago_recibido !== true && d.reserva_confirmada !== true && !texto(d.fecha_pago) && !texto(d.evento_stripe_id) && Number(d.monto_pagado || 0) === 0;
const activa = d => activas.has(String(d.estado_reserva ?? '').toLowerCase()) && sinPagar(d);

const pedida = texto(entrada.reserva_draft_id_anterior);
const candidatas = filas.filter(activa).filter(d => !pedida || String(d.id) === pedida);

let motivo = '';
let anterior = null;
if (!filas.length) motivo = 'SIN_PRERESERVA';
else if (pedida && !candidatas.length) motivo = 'LA_PRERESERVA_INDICADA_NO_ES_CAMBIABLE';
else if (!candidatas.length) motivo = filas.some(d => d.pago_recibido === true || d.reserva_confirmada === true) ? 'YA_PAGADA_O_CONFIRMADA' : 'SIN_PRERESERVA_ACTIVA';
else if (candidatas.length > 1) motivo = 'VARIAS_PRERESERVAS_ACTIVAS';
else anterior = candidatas[0];

const nuevaSolicitud = texto(entrada.solicitud_id) && texto(entrada.solicitud_id) !== texto(anterior?.solicitud_id)
  ? texto(entrada.solicitud_id)
  : 'cambio_' + texto(anterior?.id) + '_' + Date.now();

return [{ json: {
  ...entrada,
  puede_cambiar: Boolean(anterior),
  motivo_no_cambiable: motivo || null,
  reserva_draft_id_anterior: anterior ? String(anterior.id) : '',
  estado_anterior: anterior ? String(anterior.estado_reserva ?? '') : '',
  servicio_anterior: anterior ? String(anterior.servicio ?? anterior.nombre_servicio ?? '') : '',
  sucursal_anterior: anterior ? String(anterior.sucursal ?? '') : '',
  pabau_anterior_reservado: anterior ? anterior.pabau_reservado === true : false,
  pabau_citas_agua_ids: anterior ? (anterior.pabau_citas_agua_ids ?? []) : [],
  pabau_citas_masaje_ids: anterior ? (anterior.pabau_citas_masaje_ids ?? []) : [],
  solicitud_id_nueva: nuevaSolicitud,
  sucursal_solicitada: texto(entrada.sucursal),
  motivo_cambio: texto(entrada.motivo_cambio) || 'EL_CLIENTE_PIDE_OTRO_SERVICIO',
} }];

const d = $input.first().json || {};
const mensajes = {
  SIN_PRERESERVA: 'No encontré una pre-reserva activa de este contacto.',
  SIN_PRERESERVA_ACTIVA: 'No hay una pre-reserva activa que se pueda cambiar.',
  YA_PAGADA_O_CONFIRMADA: 'La pre-reserva ya tiene pago registrado: el cambio lo realiza una asesora.',
  LA_PRERESERVA_INDICADA_NO_ES_CAMBIABLE: 'La pre-reserva indicada no se puede cambiar (ya está pagada, cancelada o no existe).',
  VARIAS_PRERESERVAS_ACTIVAS: 'Hay más de una pre-reserva activa: hay que aclarar cuál se cambia.',
};
return [{ json: {
  cambio_ok: false,
  motivo: d.motivo_no_cambiable || 'NO_SE_PUEDE_CAMBIAR',
  mensaje: mensajes[d.motivo_no_cambiable] || 'No se pudo cambiar la pre-reserva.',
  reserva_draft_id_anterior: d.reserva_draft_id_anterior || null,
  servicio_anterior: d.servicio_anterior || null,
  requiere_asesora: d.motivo_no_cambiable === 'YA_PAGADA_O_CONFIRMADA' || d.motivo_no_cambiable === 'VARIAS_PRERESERVAS_ACTIVAS',
} }];

// La pre-reserva anterior solo se cancela si sus citas en Pabau no están compartidas con
// otro borrador. Las citas se cancelan una por una con la API de la sucursal.
const BASE = {
  "24077": "https://api.oauth.pabau.com/cg50463j391eb4i6hb9b315idc8id5ga90g493jf29734a4e9aj3ha5a5gb52a65",
  "24079": "https://api.oauth.pabau.com/28006aa905jfdg1jd39cbbh878bajb72h4be3ba3a339314cchdife73i3e80g1f",
  "24080": "https://api.oauth.pabau.com/a4dj4ebj49g2b15bf841hd0bafi3hb7icccdf9494gf1cc22id9606j79d29ig91",
  "24082": "https://api.oauth.pabau.com/i15b16i0cah9aif6263d82h7a7h72b0hcef5ac1698d2f2ih62ebia7f0j5e571d",
  "24221": "https://api.oauth.pabau.com/F9jYXMXcdM98vl9kvo1JsRglq2YHuIB2N7FSLPWFyRg"
};
const contexto = $('Elegir la pre-reserva a cambiar').first().json || {};
const nueva = $('Leer la nueva pre-reserva guardada').first().json?.nueva || {};
const r = $input.first().json || {};

function lista(valor) {
  if (valor === undefined || valor === null || valor === '') return [];
  if (Array.isArray(valor)) return valor.flatMap(lista);
  if (typeof valor === 'string') {
    const t = valor.trim();
    if (!t) return [];
    try { const c = JSON.parse(t); if (Array.isArray(c)) return c.flatMap(lista); } catch {}
    return t.split(',').map(x => x.trim()).filter(Boolean);
  }
  return [valor];
}

const integridad = r || {};
const ids = [...new Set([
  ...lista(contexto.pabau_citas_agua_ids),
  ...lista(contexto.pabau_citas_masaje_ids),
].map(String).filter(Boolean))];
const base = BASE[String(contexto.sucursal_anterior || '')] || null;
const puede = integridad.puede_usar_citas === true && ids.length > 0 && Boolean(base) && contexto.puede_cambiar === true;

if (!puede) {
  const motivo = !contexto.puede_cambiar ? 'SIN_PRERESERVA_ANTERIOR'
    : integridad.puede_usar_citas !== true ? 'CITAS_COMPARTIDAS_CON_OTRO_BORRADOR'
    : !ids.length ? 'LA_PRERESERVA_ANTERIOR_NO_TIENE_CITAS'
    : 'SIN_API_PABAU_PARA_LA_SUCURSAL';
  return [{ json: {
    ...contexto, ...integridad, nueva,
    omitir_cancelacion: true,
    motivo_cancelacion_pendiente: motivo,
    citas_anterior: 0,
    cancelacion_completa: false,
  } }];
}

return ids.map(appointment_id => ({ json: {
  ...contexto, ...integridad, nueva,
  omitir_cancelacion: false,
  appointment_id,
  pabau_base: base,
  citas_anterior: ids.length,
  cancelacion_completa: false,
} }));

const contexto = $('Preparar la cancelación de la anterior').first().json || {};
const preparadas = $('Preparar la cancelación de la anterior').all().map(i => i.json || {});
const respuestas = $input.all();
const ok = r => {
  const j = r.json || {};
  const codigo = Number(j.statusCode ?? (j.error ? 0 : 200));
  let cuerpo = j.body ?? j;
  if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch { cuerpo = {}; } }
  return codigo >= 200 && codigo < 300 && !j.error && cuerpo?.success !== false;
};
// La respuesta de Pabau no repite el ID: se toma de la cita que se envió, por orden.
const detalle = respuestas.map((r, i) => ({ appointment_id: String(preparadas[i]?.appointment_id ?? '') || null, cancelada: ok(r) }));
const fallidas = detalle.filter(x => !x.cancelada).map(x => x.appointment_id);
return [{ json: {
  ...contexto,
  detalle_cancelacion: detalle,
  citas_canceladas: detalle.filter(x => x.cancelada).length,
  citas_fallidas: fallidas,
  cancelacion_completa: respuestas.length > 0 && fallidas.length === 0,
} }];

const prep = $('Preparar la cancelación de la anterior').first().json || {};
const guardada = $('Leer la nueva pre-reserva guardada').first().json || {};
const nueva = guardada.nueva || {};
const salida = (nombre) => { try { const n = $(nombre); return n && n.isExecuted ? (n.first().json || {}) : null; } catch { return null; } };
const validacion = salida('Validar cancelación de la anterior');
// La base es la que manda: se relee la pre-reserva anterior antes de declararla cerrada.
const verificado = salida('Verificar estado de la anterior');
const borradorAnterior = verificado?.borrador && typeof verificado.borrador === 'object' ? verificado.borrador : {};
const estadoAnteriorEnBase = String(borradorAnterior.estado_reserva ?? '');
const cierreRegistrado = ['expirado_sin_pago', 'requiere_revision'].includes(estadoAnteriorEnBase)
  && borradorAnterior.pabau_reservado === false;
const cancelada = prep.omitir_cancelacion !== true && validacion?.cancelacion_completa === true && cierreRegistrado;
const pendiente = !cierreRegistrado || prep.omitir_cancelacion === true || (validacion && validacion.cancelacion_completa !== true);

return [{ json: {
  cambio_ok: true,
  reserva_draft_id_nuevo: String(nueva.id ?? ''),
  reserva_draft_id_anterior: String(prep.reserva_draft_id_anterior ?? ''),
  servicio_nuevo: String(nueva.servicio ?? prep.servicio ?? ''),
  sucursal: String(nueva.sucursal ?? prep.sucursal ?? ''),
  fecha: String(nueva.jacuzzi_inicio || nueva.masaje_inicio || '').slice(0, 10),
  horario: String(nueva.jacuzzi_inicio || nueva.masaje_inicio || '').slice(11, 16),
  numero_personas: Number(nueva.numero_personas ?? prep.numero_personas ?? 0) || null,
  solicitud_id_nueva: String(nueva.solicitud_id ?? prep.solicitud_id_nueva ?? ''),
  pre_reserva_anterior_cancelada: cancelada,
  cierre_anterior_registrado: cierreRegistrado,
  estado_anterior_en_base: estadoAnteriorEnBase || null,
  aviso: pendiente ? 'LA_PRERESERVA_ANTERIOR_QUEDO_PENDIENTE_DE_CANCELAR_EN_PABAU' : null,
  motivo_cancelacion_pendiente: pendiente ? (prep.motivo_cancelacion_pendiente || 'CANCELACION_INCOMPLETA') : null,
  citas_canceladas: Number(validacion?.citas_canceladas ?? 0),
  necesita_enlace_nuevo: true,
  mensaje: 'La pre-reserva se actualizó al servicio nuevo y quedó retenida en Pabau. Genera el enlace de pago de la pre-reserva nueva y compártelo.',
} }];

const guardada = $input.first().json || {};
const prep = $('Elegir la pre-reserva a cambiar').first().json || {};
return [{ json: {
  cambio_ok: false,
  motivo: 'NO_SE_PUDO_GUARDAR_LA_NUEVA_PRERESERVA',
  mensaje: 'No se pudo guardar la pre-reserva del servicio nuevo. La pre-reserva anterior NO se tocó.',
  detalle_guardado: guardada,
  reserva_draft_id_anterior: prep.reserva_draft_id_anterior || null,
  pre_reserva_anterior_intacta: true,
  requiere_asesora: false,
} }];
